report.remediation:
Change `signalled_at` to be captured just before calling `wind_down_coordinator`, so the coordinator grace is measured from after unit wind-down completes. Alternatively, pass a separate absolute deadline computed as `Instant::now() + grace.coordinator` inside `wind_down_coordinator` after `wind_down_units` returns. The simplest fix:

```rust
wind_down_units(run_dir, grace.units);
if let Some((pgid, _signalled_at)) = coordinator_group {
    // Re-measure deadline after unit wind-down so the coordinator
    // gets its full grace starting now, not from when it was signalled.
    wind_down_coordinator(pgid, Instant::now() + grace.coordinator);
}
```

recommended_patch.diff:
--- a/crates/rupu-agentiflow/src/reaper.rs
+++ b/crates/rupu-agentiflow/src/reaper.rs
@@ -355,8 +355,9 @@ pub fn hard_stop_with(
     wind_down_units(run_dir, grace.units);
-    if let Some((pgid, signalled_at)) = coordinator_group {
-        wind_down_coordinator(pgid, signalled_at + grace.coordinator);
+    if let Some((pgid, _signalled_at)) = coordinator_group {
+        // Deadline is measured after unit wind-down so the coordinator
+        // receives its full grace regardless of how long units took.
+        wind_down_coordinator(pgid, Instant::now() + grace.coordinator);
     }

