@@ -409,9 +409,10 @@ fn wind_down_units(run_dir: &Path, grace: Duration) {
     for pgid in signalled {
-        if pid_is_running(pgid) {
-            tracing::warn!(pgid, "a unit outlived its SIGTERM grace; sending SIGKILL");
-            if !kill_group(pgid) {
-                tracing::warn!(pgid, "could not SIGKILL a unit's process group");
-            }
+        // Skip the pid_is_running pre-check: calling kill_group unconditionally
+        // removes the TOCTOU window where the pgid could be recycled between
+        // the check and the kill. kill_group returns false (ESRCH) for an
+        // already-dead group, which is safe to ignore.
+        tracing::warn!(pgid, "a unit outlived its SIGTERM grace; sending SIGKILL");
+        if !kill_group(pgid) {
+            tracing::debug!(pgid, "SIGKILL to unit group returned error (group may already be gone)");
         }
     }
